source('code/analysis/main/engine.R')
dir.create(file.path(OUT,'descriptives'),showWarnings=FALSE)
# Eligible union across all cohort-specific matching pools; measured in 2010 for baseline table.
ids<-list()
for(g in 2011:2019){cv<-c(x$match_covars_full,if(g>=2012)paste0(c('log_rac','log_wac','log_seer_pop','rac_total','wac_total'),'_recent'),if(g>=2015)paste0(c('log_rac','log_wac','log_seer_pop','rac_total','wac_total'),'_early'))
 ids[[as.character(g)]]<-p%>%filter(year==g-1,residential_eligible,min_pre_population>=100,is_control|first_pis_year==g)%>%filter(if_all(all_of(cv),is.finite))%>%select(tract_id)
}
e<-bind_rows(ids)%>%distinct()
vars<-c('seer_total_population','seer_share_nh_black','seer_share_hispanic','seer_age_share_under29','seer_age_share_55plus','acs2010_median_hh_income','rac_total','rac_earn_le_1250','rac_earn_1251_3333','rac_earn_ge_3333','wac_total','wac_earn_le_1250','wac_earn_1251_3333','wac_earn_ge_3333','emp_pop_ratio')
b<-p%>%filter(year==2010)%>%semi_join(e,by='tract_id')
s<-map_dfr(vars,function(y)b%>%group_by(is_control)%>%summarise(variable=y,mean=mean(.data[[y]][is.finite(.data[[y]])]),sd=sd(.data[[y]][is.finite(.data[[y]])]),n=sum(is.finite(.data[[y]])),.groups='drop'))
write_csv(s,file.path(OUT,'descriptives/baseline.csv'));write_csv(b%>%count(is_control),file.path(OUT,'descriptives/baseline_tract_counts.csv'))
c<-p%>%filter(year==2010,!is_control)%>%transmute(tract_id,cohort=first_pis_year,eligible=tract_id%in%e$tract_id,matched=tract_id%in%pairs$tract_id[pairs$group=='pooled'&pairs$treated_cohort==1])%>%group_by(cohort)%>%summarise(original=n(),eligible=sum(eligible),matched=sum(matched),.groups='drop')
write_csv(c,file.path(OUT,'descriptives/cohorts.csv'))
r<-x$raw%>%filter(valid_tract,str_trim(type)=='1',between(pis_year,2011,2019))%>%mutate(tract_id=as.numeric(tract_digits),total=suppressWarnings(as.numeric(n_units)),li=suppressWarnings(as.numeric(li_units)),invalid=is.na(total)|total<=0|total!=floor(total)|(!is.na(li)&li>total),total=if_else(invalid,NA_real_,total))
first<-r%>%inner_join(p%>%distinct(tract_id,first_pis_year),by='tract_id')%>%filter(pis_year==first_pis_year)%>%group_by(tract_id)%>%summarise(first_projects=n(),first_units=if(anyNA(total))NA_real_ else sum(total),.groups='drop')
cum<-r%>%group_by(tract_id)%>%summarise(projects=n(),cumulative_units=if(anyNA(total))NA_real_ else sum(total),.groups='drop')
scale<-p%>%filter(year==2010,!is_control)%>%select(tract_id,seer_total_population)%>%left_join(first,by='tract_id')%>%left_join(cum,by='tract_id')%>%mutate(eligible=tract_id%in%e$tract_id,matched=tract_id%in%pairs$tract_id[pairs$group=='pooled'&pairs$treated_cohort==1])
write_csv(scale,file.path(OUT,'descriptives/first_and_cumulative_units.csv'))
summary<-map_dfr(c('original','eligible','matched'),function(s){d<-if(s=='original')scale else filter(scale,.data[[s]]);tibble(sample=s,tracts=nrow(d),first_mean=mean(d$first_units,na.rm=TRUE),first_median=median(d$first_units,na.rm=TRUE),first_sd=sd(d$first_units,na.rm=TRUE),cumulative_mean=mean(d$cumulative_units,na.rm=TRUE),cumulative_median=median(d$cumulative_units,na.rm=TRUE),cumulative_sd=sd(d$cumulative_units,na.rm=TRUE),first_per1000=mean(d$first_units/d$seer_total_population*1000,na.rm=TRUE),cumulative_per1000=mean(d$cumulative_units/d$seer_total_population*1000,na.rm=TRUE),first_share=mean(d$first_units/d$cumulative_units,na.rm=TRUE),one_project_share=mean(d$projects==1,na.rm=TRUE))})
write_csv(summary,file.path(OUT,'descriptives/project_scale_summary.csv'))
# Actual model-specific treated sets, not all historical project tracts.
files<-list.files(file.path(OUT,'main'),pattern='treated_ids.csv$',recursive=TRUE,full.names=TRUE)
id<-map_dfr(files,~read_csv(.x,show_col_types=FALSE))%>%filter(outcome%in%c('rac_total','wac_total','seer_total_population'))%>%left_join(first,by='tract_id')
stopifnot(!anyNA(id$first_projects))
h<-id%>%group_by(group,specification,outcome)%>%summarise(treated_tracts=n(),valid_unit_tracts=sum(is.finite(first_units)),mean_first_year_total=mean(first_units,na.rm=TRUE),.groups='drop')
write_csv(h,file.path(OUT,'descriptives/housing_scale_by_estimation_sample.csv'));write_csv(id,file.path(OUT,'descriptives/housing_scale_treated_ids.csv'))
